```js
// Módulo simple con closure y this
const counter = (() => {
  let total = 0;               // variable privada (closure)
  return {
    inc() {                    // método que usa this implícito
      total++;
      console.log(this === counter); // true
    },
    get() { return total; }
  };
})();

counter.inc();   // 1
counter.inc();   // 2
console.log(counter.get()); // 2
```
